#include "kernel_operator.h"
constexpr int32_t BUFFER_NUM = 1;
class KernelXor {
public:
__aicore__ inline KernelXor() {}
__aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, uint32_t totalLength, uint32_t
totalLength2, uint32_t tilenum, uint32_t tmpSize, uint32_t mcount)
{
this->totalLength = totalLength;
this->blockLength = totalLength / AscendC::GetBlockNum();
this->blockLength2 = totalLength2 / AscendC::GetBlockNum();
this->tilenum = tilenum;
this->tmpSize = tmpSize;
this->mcount = mcount;
this->tileLength = this->blockLength / tilenum / BUFFER_NUM;
this->tileLength2 = this->blockLength2 / tilenum / BUFFER_NUM;
xGm.SetGlobalBuffer((__gm__ int16_t *)x + this->blockLength * AscendC::GetBlockIdx(), this-
>blockLength);
yGm.SetGlobalBuffer((__gm__ int16_t *)y + this->blockLength2 * AscendC::GetBlockIdx(), this-
>blockLength2);
zGm.SetGlobalBuffer((__gm__ int16_t *)z + this->blockLength * AscendC::GetBlockIdx(), this-
>blockLength);
if (this->tmpSize != 0) {
pipe.InitBuffer(tmpQueue, BUFFER_NUM, this->tmpSize);
}
pipe.InitBuffer(inQueueX, BUFFER_NUM, this->tileLength * sizeof(int16_t));
pipe.InitBuffer(inQueueY , BUFFER_NUM, this->tileLength2 * sizeof(int16_t));
pipe.InitBuffer(outQueueZ, BUFFER_NUM, this->tileLength * sizeof(int16_t));
}
__aicore__ inline void Process()
{
int32_t loopCount = this->tilenum * BUFFER_NUM;
for (int32_t i = 0; i < loopCount; i++) {
CopyIn(i);
Compute(i);
CopyOut(i);
}
}
