if (sizeflag == 0) {
tiling.set_tmpSize(minValue);
} else if (sizeflag == 1) {
tiling.set_tmpSize(maxValue);
} else if (sizeflag == 2) {
tiling.set_tmpSize(0);
}
tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()-
